+glib::wrapper! {
+    pub struct Canvas(ObjectSubclass<imp::Canvas>)
+        @extends gtk::DrawingArea, gtk::Widget,
+        @implements gtk::Accessible, gtk::Buildable, gtk::ConstraintTarget;
+}
